import { create, StateCreator } from 'zustand'
import { persist } from 'zustand/middleware'

interface globalState {
  globalLoading: boolean
  setGlobalLoading: (value: boolean) => void
  isScrollTop: boolean
  setIsScrollTop: (value: boolean) => void
  scrollYgtZero: boolean
  setScrollYgtZero: (value: boolean) => void
  phantomInstance: any
  setPhantomInstance: (value: any) => void
  dlmmTutorialStep: number
  setDlmmTutorialStep: (value: number) => void
  isOpenPortfolioDrawer: boolean
  setIsOpenPortfolioDrawer: (status: boolean) => void
}

const store: StateCreator<globalState> = (set, get) => ({
  globalLoading: true,
  setGlobalLoading: (value: boolean) => {
    set(() => ({
      globalLoading: value
    }))
  },
  scrollYgtZero: false,
  setScrollYgtZero: (value: boolean) => {
    set(() => ({
      scrollYgtZero: value
    }))
  },
  isScrollTop: false,
  setIsScrollTop: (value: boolean) => {
    set(() => ({
      isScrollTop: value
    }))
  },
  phantomInstance: undefined,
  setPhantomInstance: (value: any) => {
    set(() => ({
      phantomInstance: value
    }))
  },
  dlmmTutorialStep: 0,
  setDlmmTutorialStep: (value: number) => {
    set(() => ({
      dlmmTutorialStep: value
    }))
  },
  isOpenPortfolioDrawer: false,
  setIsOpenPortfolioDrawer: (status: boolean) => {
    set(() => ({
      isOpenPortfolioDrawer: status
    }))
  }
})

const useGlobalStore = create(
  persist(store, {
    name: 'global-store',
    partialize: state => {
      const { dlmmTutorialStep } = state
      return { dlmmTutorialStep }
    }
  })
)
export default useGlobalStore
