import { Transaction } from '@mysten/sui/transactions'
import { fromBase64, toBase64 } from '@mysten/sui/utils'
import type {
  IdentifierArray,
  StandardConnectFeature,
  StandardConnectMethod,
  StandardDisconnectFeature,
  StandardDisconnectMethod,
  StandardEventsFeature,
  StandardEventsListeners,
  StandardEventsOnMethod,
  SuiSignAndExecuteTransactionFeature,
  SuiSignAndExecuteTransactionMethod,
  SuiSignPersonalMessageFeature,
  SuiSignPersonalMessageMethod,
  SuiSignTransactionFeature,
  SuiSignTransactionMethod,
  Wallet,
  WalletIcon
} from '@mysten/wallet-standard'
import {
  getWallets,
  ReadonlyWalletAccount,
  StandardConnect,
  StandardDisconnect,
  StandardEvents,
  // SUI_CHAINS,
  SuiSignAndExecuteTransaction,
  SuiSignPersonalMessage,
  SuiSignTransaction
} from '@mysten/wallet-standard'
import type { CustomCaipNetwork } from '@reown/appkit-universal-connector'
import { UniversalConnector } from '@reown/appkit-universal-connector'
import { Buffer } from 'buffer'
import type { Emitter } from 'mitt'
import mitt from 'mitt'
import type { InferOutput } from 'valibot'
import { boolean, object, string } from 'valibot'

// -- Types --
type WalletEventsMap = {
  [E in keyof StandardEventsListeners]: Parameters<StandardEventsListeners[E]>[0]
}

type SupportedNetwork = 'mainnet' | 'testnet' | 'devnet' | 'localnet'

export type GetClient = (network: SupportedNetwork) => Experimental_BaseClient
type WalletMetadata = InferOutput<typeof WalletMetadataSchema>

// -- Constants --
const icon =
  'data:image/svg+xml;base64,'
export const WALLETCONNECT_WALLET_NAME = 'WalletConnect' as const
const walletAccountFeatures = ['sui:signTransaction', 'sui:signAndExecuteTransaction', 'sui:signPersonalMessage'] as const

const SUI_CHAINS: any = ['sui:mainnet', 'sui:testnet', 'sui:devnet']
const SUICaipNetworks: CustomCaipNetwork<'sui'>[] = SUI_CHAINS.map((chain: any) => {
  const [_, chainId] = chain.split(':')
  return {
    id: chainId,
    chainNamespace: 'sui',
    caipNetworkId: chain,
    name: `Sui ${chainId}`,
    nativeCurrency: { name: 'SUI', symbol: 'SUI', decimals: 9 },
    rpcUrls: { default: { http: [`https://sui-${chainId}.gateway.tatum.io`] } }
  }
})

const WalletMetadataSchema = object({
  id: string('Wallet ID is required'),
  walletName: string('Wallet name is required'),
  icon: string('Icon must be a valid wallet icon format'),
  enabled: boolean('Enabled is required')
})

const toStandardAccounts = (accounts: { address: string; pubkey: string }[], chains: IdentifierArray) => {
  return accounts.map(account => {
    return new ReadonlyWalletAccount({
      address: account.address,
      chains,
      features: walletAccountFeatures,
      publicKey: fromBase64(account.pubkey)
    })
  })
}

// -- Wallet --
export class WalletConnectWallet implements Wallet {
  #id: string
  #events: Emitter<WalletEventsMap>
  #accounts: ReadonlyWalletAccount[]
  #walletName: string
  #icon: WalletIcon
  #connector?: UniversalConnector
  #projectId: string
  #getClient: GetClient

  get name() {
    return this.#walletName
  }

  get id() {
    return this.#id
  }

  get icon() {
    return this.#icon
  }

  get version() {
    return '1.0.0' as const
  }

  get chains() {
    return SUI_CHAINS
  }

  get accounts() {
    return this.#accounts
  }

  get features(): StandardConnectFeature &
    StandardDisconnectFeature &
    StandardEventsFeature &
    SuiSignTransactionFeature &
    SuiSignPersonalMessageFeature &
    SuiSignAndExecuteTransactionFeature {
    return {
      [StandardConnect]: {
        version: '1.0.0',
        connect: this.#connect
      },
      [StandardDisconnect]: {
        version: '1.0.0',
        disconnect: this.#disconnect
      },
      [StandardEvents]: {
        version: '1.0.0',
        on: this.#on
      },
      [SuiSignTransaction]: {
        version: '2.0.0',
        signTransaction: this.#signTransaction
      },
      [SuiSignPersonalMessage]: {
        version: '1.1.0',
        signPersonalMessage: this.#signPersonalMessage
      },
      [SuiSignAndExecuteTransaction]: {
        version: '2.0.0',
        signAndExecuteTransaction: this.#signAndExecuteTransaction
      }
    }
  }

  constructor({ metadata, projectId, getClient }: { metadata: WalletMetadata; projectId: string; getClient: GetClient }) {
    this.#id = metadata.id
    this.#accounts = []
    this.#events = mitt()
    this.#walletName = metadata.walletName
    this.#icon = icon
    this.#projectId = projectId
    this.#getClient = getClient
    this.init()
  }

  async init() {
    this.#connector = await UniversalConnector.init({
      projectId: this.#projectId,

      // TODO: Use dapp metadata
      metadata: {
        name: this.#walletName,
        description: 'WalletConnect',
        icon: this.#icon
      },
      networks: [
        {
          namespace: 'sui',
          methods: ['sui_signTransaction', 'sui_signPersonalMessage', 'sui_signAndExecuteTransaction', 'sui_getAccounts'],
          events: ['chainChanged', 'accountsChanged'],
          chains: SUICaipNetworks
        }
      ],
      modalConfig: {
        themeVariables: {
          '--w3m-z-index': 2147483647
        }
      }
    })
    this.#accounts = await this.#getPreviouslyAuthorizedAccounts()
  }

  #signTransaction: SuiSignTransactionMethod = async ({ transaction, account, chain }) => {
    const tx = await transaction.toJSON()
    const parsedTransaction = Transaction.from(tx)

    let serializedTxBlock
    const [, network] = chain.split(':')
    const client = this.#getClient(network as SupportedNetwork)

    // Handle different transaction types more robustly
    if (typeof parsedTransaction.build === 'function') {
      serializedTxBlock = await parsedTransaction.build({
        // client: new SuiClient({url: getFullnodeUrl('mainnet')}),
        client
      })
    } else {
      throw new Error(`Unsupported transaction type: `)
    }

    const transactionData = Buffer.from(serializedTxBlock).toString('base64')

    const response = (await this.#connector?.request(
      {
        method: 'sui_signTransaction',
        params: {
          //   transaction: tx,
          transaction: transactionData,
          address: account.address
        }
      },
      chain
    )) as { transactionBytes: string; signature: string }

    return {
      bytes: response.transactionBytes,
      signature: response.signature
    }
  }

  #signAndExecuteTransaction: SuiSignAndExecuteTransactionMethod = async ({ transaction, account, chain }) => {
    const [, network] = chain.split(':')
    const client = this.#getClient(network as SupportedNetwork)
    const data = await transaction.toJSON()
    const parsedTransaction = Transaction.from(data)
    const bytes = await parsedTransaction.build({ client })

    const transactionData = Buffer.from(bytes).toString('base64')
    const response = (await this.#connector?.request(
      {
        method: 'sui_signAndExecuteTransaction',
        params: {
          transaction: transactionData,
          address: account.address
        }
      },
      chain
    )) as { digest: string }

    const tx = await client.core.waitForTransaction({
      digest: response.digest
    })

    return {
      digest: response.digest,
      signature: tx.transaction.signatures[0] ?? '',
      bytes: toBase64(bytes),
      effects: tx.transaction.effects.bcs ? toBase64(tx.transaction.effects.bcs) : ''
    }
  }

  #signPersonalMessage: SuiSignPersonalMessageMethod = async ({ message, account, chain }) => {
    const messageString = new TextDecoder().decode(message)
    const response = (await this.#connector?.request(
      {
        method: 'sui_signPersonalMessage',
        params: {
          message: messageString,
          address: account.address
        }
      },
      chain ?? 'sui:mainnet'
    )) as { signature: string }

    return {
      signature: response.signature,
      bytes: toBase64(message)
    }
  }

  #on: StandardEventsOnMethod = (event, listener) => {
    this.#events.on(event, listener)
    return () => this.#events.off(event, listener)
  }

  #setAccounts(accounts: ReadonlyWalletAccount[]) {
    this.#accounts = accounts
    this.#events.emit('change', { accounts: this.accounts })
  }

  #getAccounts = async () => {
    const amountList = this.#connector?.provider?.namespaces?.sui?.accounts ?? []
    const formattedAmountList = amountList.map((item: string) => {
      const address = item?.split(':')?.[2]
      return {
        address,
        pubkey: address
      }
    })
    let accounts = formattedAmountList || []

    if (!accounts?.length) {
      accounts = (await this.#connector?.request({ method: 'sui_getAccounts' }, 'sui:mainnet')) as {
        address: string
        pubkey: string
      }[]
    }

    return toStandardAccounts(accounts, this.chains)
  }

  #connect: StandardConnectMethod = async input => {
    if (input?.silent) {
      const accounts = await this.#getPreviouslyAuthorizedAccounts()
      if (accounts.length > 0) {
        this.#setAccounts(accounts)
        return { accounts }
      }
    }

    if (!this.#connector?.provider?.session?.namespaces?.sui) {
      await this.#connector?.connect()
    }

    const accounts = await this.#getAccounts()
    this.#setAccounts(accounts)

    return { accounts: this.accounts }
  }

  #getPreviouslyAuthorizedAccounts = async () => {
    const session = this.#connector?.provider?.session
    if (!session?.namespaces?.sui) {
      return []
    }

    const accounts = JSON.parse(session.sessionProperties?.['sui_getAccounts'] ?? '[]') as {
      address: string
      pubkey: string
    }[]

    return toStandardAccounts(accounts, SUI_CHAINS)
  }

  #disconnect: StandardDisconnectMethod = async () => {
    this.#connector?.disconnect()
    this.#setAccounts([])
  }

  updateMetadata(metadata: WalletMetadata) {
    this.#id = metadata.id
    this.#walletName = metadata.walletName
  }
}
type RegisterWalletConnectWallet = {
  projectId: string
  getClient: GetClient
  metadata?: WalletMetadata
}

export function registerWalletConnectWallet({ projectId, getClient, metadata }: RegisterWalletConnectWallet) {
  const wallets = getWallets()

  let unregister: (() => void) | null = null

  // listen for wallet registration
  wallets.on('register', (wallet: Wallet) => {
    if (wallet.id === 'walletconnect') {
      unregister?.()
    }
  })

  const extension = wallets.get().find((wallet: Wallet) => wallet.id === 'walletconnect')
  if (extension) {
    return
  }

  const fullMetadata = {
    id: 'walletconnect',
    walletName: 'Wallet Connect',
    icon,
    enabled: true,
    ...metadata
  }

  const walletConnectWalletInstance = new WalletConnectWallet({
    metadata: fullMetadata,
    projectId,
    getClient
  })
  unregister = wallets.register(walletConnectWalletInstance)

  walletConnectWalletInstance.updateMetadata({
    ...fullMetadata,
    enabled: true
  })

  return {
    wallet: walletConnectWalletInstance,
    unregister
  }
}
