import useQueryParams from '@cetus/hooks/src/useQueryParams'
import useGlobalStore from '@cetus/stores/src/global'
import { Flex, Image } from '@chakra-ui/react'
import { lazy, Suspense, useMemo } from 'react'
import { useLocation } from 'react-router-dom'
import { IMenusProps } from '../type'
const UserActions = lazy(() => import('../userActions'))

const H5Header = ({ menus, logo, setting, notifications, jump, isCetusPump, children }: IMenusProps) => {
  const { pathname } = useLocation()
  const { tabDetail } = useQueryParams()
  const { scrollYgtZero } = useGlobalStore()

  const firstPathPart = pathname.split('/').filter(Boolean)[0]
  const isShowBg = useMemo(() => {
    return (firstPathPart !== 'portfolio' && firstPathPart !== 'invite') || scrollYgtZero
  }, [scrollYgtZero, firstPathPart])
  return (
    <>
      <Flex
        w="100%"
        justifyContent="space-between"
        align="center"
        p="0px 8px 0px 12px"
        h="48px"
        position="sticky"
        zIndex={tabDetail ? '-1' : '999'}
        top="0px"
        background={!isShowBg ? 'transparent' : 'bg_primary'}
      >
        <Image src="/images/img-logo@2x.png" h="32px" alt="logo" onClick={() => jump('/')} />

        <Suspense fallback={<div />}>
          <UserActions menus={menus} logo={logo} setting={setting} notifications={notifications} jump={jump} isCetusPump={isCetusPump}>
            {children}
          </UserActions>
        </Suspense>
      </Flex>
    </>
  )
}

export default H5Header
