import { camelCase, snakeCase } from 'lodash-es'

export const formatToken = (token: Record<string, any>) => {
  const _token: Record<string, any> = {}
  for (const key in token) {
    if (typeof token[key] !== 'object' || Array.isArray(token[key]) || token[key] === null) {
      _token[snakeCase(key)] = token[key]
    } else {
      for (const property in token[key]) {
        _token[snakeCase(property)] = token[key][property]
      }
    }
  }
  return _token
}

export const camelCaseObject = (obj: Record<string, any>) => {
  const newObj: Record<string, any> = {}
  for (const key in obj) {
    if (typeof obj[key] !== 'object' || obj[key] === null) {
      newObj[camelCase(key)] = obj[key]
    } else if (Array.isArray(obj[key])) {
      newObj[camelCase(key)] = obj[key].map(item => camelCaseObject(item))
    } else {
      newObj[camelCase(key)] = camelCaseObject(obj[key])
    }
  }
  return newObj
}
