import { useTokenSelect } from '@/hook'
import { useDebounceFunction } from '@cetus/hooks'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { useAccountStore } from '@cetus/stores'
import useTokenStore from '@cetus/stores/src/token'
import useTokenPriceStore from '@cetus/stores/src/tokenPrice'
import useTokenSelectStore from '@cetus/stores/src/useTokenSelectStore'
import { Token } from '@cetus/types'
import { Icon } from '@cetus/ui-kit'
import { Box, Button, Center, Flex, HStack, Skeleton, SkeletonCircle, Text, VStack } from '@chakra-ui/react'
import { lazy, Suspense, useEffect, useMemo, useState } from 'react'
import SelectTab from '../SelectTab'
import SingleTokenInfo from '../SingleTokenInfo'
import { SearchInput } from './SearchInput'
import { SelectType } from './type'

const CollectListBox = lazy(() => import('./CollectListBox'))
const TokenList = lazy(() => import('./TokenList'))

interface TokenSelectCardProps {
  isOpen: boolean
  haveImport?: boolean // 是否可以导入
  isDisableSelectTokenItem?: boolean // 是否禁止选择重复token
  isDcaSelect?: boolean // 是否是dca选择弹窗
  whiteTokenList?: Token[] // 白名单tokenlist
  isShowCollectListBox?: boolean // 是否显示收藏token
  isShowHotList?: boolean // 是否显示热门token
  isShowOperate?: boolean // 是否显示最后三个操作按钮
  isShowTokenListTab?: boolean //是否显示default imported切换
  isShowLabelTab?: boolean // 是否显示label筛选
  noDataHaveImg?: boolean // 无数据样式是否展示图片
  noClickImportItem?: boolean
  isShowCoinInfo?: boolean
  bg?: string
  isWidget?: boolean
  tokenListMaxHeight?: string
  onClose: () => void
  onGoplusTokenClick?: (tokenInfo: Token) => void
  isShowTokenName?: boolean
  showSearchInput?: boolean
  selectType?: SelectType
}

interface SingleTokenSelectCardProps extends TokenSelectCardProps {
  maxSelectNum: number
  onSelectToken: (tokenInfo: Token) => void
  value: string | Token
  selectType: 'single'
}

interface MultipleTokenSelectCardProps extends TokenSelectCardProps {
  maxSelectNum: number
  onSelectToken: (tokens: Token[]) => void
  value: string[] | Token[]
  selectType: 'multiple'
}

function TokenSelectCard(props: SingleTokenSelectCardProps): any
function TokenSelectCard(props: MultipleTokenSelectCardProps): any
function TokenSelectCard(props: SingleTokenSelectCardProps | MultipleTokenSelectCardProps) {
  const {
    isWidget = false,
    isOpen,
    onClose,
    onSelectToken,
    haveImport,
    value,
    isDisableSelectTokenItem = false,
    isDcaSelect,
    whiteTokenList,
    isShowCollectListBox = true,
    isShowHotList = true,
    isShowTokenListTab = true,
    isShowLabelTab = true,
    tokenListMaxHeight,
    noDataHaveImg = true,
    noClickImportItem = false,
    isShowOperate = true,
    bg,
    onGoplusTokenClick,
    isShowTokenName,
    showSearchInput = true,
    selectType = 'single',
    maxSelectNum = 1,
    isShowCoinInfo
  } = props

  const { filterTokenListFun, filterTokenWithLabel, getImportTokenList, delImportTokenList, updateImportTokenList, sortWithTokenList } =
    useTokenSelect()
  const { setFilterTokenLoading, setShowImportBtn, importTokenList, filterTokenLoading, filterTokenList, setTokenModalOpacity, userCollectList } =
    useTokenSelectStore()
  const { verifiedTokenMap } = useTokenStore()
  const [inputValue, setInputValue] = useState('')
  const [selectTokens, setSelectTokens] = useState<string[] | Token[]>([])
  useEffect(() => {
    if (Array.isArray(value)) {
      setSelectTokens(value)
    }
  }, [value])
  const changeInputValue = (value: string) => {
    const regValue = value.replace(/[^[a-zA-Z0-9\s]+$/g, '')
    setInputValue(regValue)
    if (regValue) {
      setFilterTokenLoading(true)
      debouncedFilter(regValue)
    }
  }

  const debouncedFilter = useDebounceFunction((value: string) => {
    console.log('🚀🚀🚀 ~ TokenSelectCard.tsx:86 ~ debouncedFilter ~ useDebounceFunction:')
    if (whiteTokenList && whiteTokenList.length > 0) {
      filterTokenListFun(value, whiteTokenList, [], false, false)
    } else {
      filterTokenListFun(value, Array.from(verifiedTokenMap?.values()), importTokenList, haveImport)
    }
  }, 500)

  const selectToken = (tokenInfo: Token) => {
    if (selectType === 'single') {
      if (isDisableSelectTokenItem) {
        if (value !== tokenInfo.coin_type || value?.coin_type !== tokenInfo?.coin_type) {
          onSelectToken(tokenInfo)
          onClose()
        }
      } else {
        onSelectToken(tokenInfo)
        onClose()
      }
    } else {
      const newValue = [...selectTokens]
      if (typeof newValue?.[0] === 'string') {
        if (newValue.includes(tokenInfo.coin_type)) {
          newValue.splice(newValue.indexOf(tokenInfo.coin_type), 1)
        } else {
          if (newValue?.length < maxSelectNum) {
            newValue.push(tokenInfo.coin_type)
          }
        }
        setSelectTokens(newValue)
      } else {
        const index = (newValue as Token[]).findIndex(item => item?.coin_type === tokenInfo.coin_type)
        if (index > -1) {
          newValue.splice(index, 1)
        } else {
          if (newValue?.length < maxSelectNum) {
            newValue.push(tokenInfo)
          }
        }
        setSelectTokens(newValue)
      }
    }
  }

  const tabList = [
    {
      label: 'Watchlist',
      value: 'Watchlist'
    },
    {
      label: 'Default',
      value: 'Default'
    },
    {
      label: 'Imported',
      value: 'Imported'
    }
  ]

  const labelList = [
    {
      label: 'All',
      value: 'All'
    },
    // {
    //   label: 'Native',
    //   value: 'Native'
    // },
    {
      label: 'Wormhole',
      value: 'Wormhole'
    }
    // {
    //   label: 'Celer',
    //   value: 'Celer'
    // }
  ]

  const [currentTab, setCurrentTab] = useState('Default')
  const [currentLabel, setCurrentLabel] = useState('All')

  const { getCollectList, getDefaultTokenList, getTabByAddress, getUserCollectList } = useTokenSelect()
  const [isMounted, setIsMounted] = useState(false)

  useEffect(() => {
    setIsMounted(true)
  }, [])
  useEffect(() => {
    if (isMounted && verifiedTokenMap && verifiedTokenMap.size > 0) {
      getDefaultTokenList()
    }
    if (isMounted) {
      getImportTokenList()
      getUserCollectList()
    }
  }, [verifiedTokenMap?.size, isMounted])

  useEffect(() => {
    if (verifiedTokenMap.size > 0) {
      getCollectList()
    }
  }, [verifiedTokenMap])

  const [updateImport, setUpdateImport] = useState(false)
  const shouldUpdate = !updateImport && verifiedTokenMap.size > 0 && importTokenList?.length > 0
  useEffect(() => {
    if (shouldUpdate) {
      updateImportTokenList()
      setUpdateImport(true)
    }
  }, [shouldUpdate])

  useEffect(() => {
    setTokenModalOpacity(1)
    if (!isOpen) {
      console.log('🚀🚀🚀 ~ file: index.tsx:164 ~ useEffect ~ tab22222')
      setCurrentTab('Default')
      setCurrentLabel('All')
      setInputValue('')
      setShowImportBtn(false)
    }
  }, [isOpen])

  // const [tokenList, setTokenList] = useState<Token[]>([])
  const { coinPriceObj } = useTokenPriceStore()
  const { currentAccount } = useAccountStore()

  const tokenList = useMemo(() => {
    if (filterTokenLoading) {
      return []
    }
    if (inputValue) {
      return filterTokenList
    } else {
      // toDo: 没看到，临时加了Default tab判断来解决Dca 的imported和watchlist展示所有白名单coin list问题

      if (whiteTokenList && whiteTokenList.length > 0 && currentTab == 'Default') {
        const keywords = Array.isArray(value) ? value?.map(item => item?.coin_type || item) : value?.coin_type || value

        return sortWithTokenList(currentLabel !== 'All' ? filterTokenList : whiteTokenList, keywords)
      } else {
        const keywords = Array.isArray(value) ? value?.map(item => item?.coin_type || item) : value?.coin_type || value
        if (currentTab == 'Default') {
          return sortWithTokenList(currentLabel !== 'All' ? filterTokenList : Array.from(verifiedTokenMap?.values()), keywords)
        } else if (currentTab == 'Imported') {
          return sortWithTokenList(importTokenList, keywords)
        } else {
          return sortWithTokenList(userCollectList, keywords)
        }
      }
    }
  }, [
    inputValue,
    filterTokenList,
    filterTokenLoading,
    currentLabel,
    currentTab,
    importTokenList,
    whiteTokenList,
    verifiedTokenMap,
    coinPriceObj,
    currentAccount?.address,
    userCollectList
  ])

  useEffect(() => {
    if (value && verifiedTokenMap && verifiedTokenMap.size > 0) {
      const keyword = Array.isArray(value) ? value?.map(item => item?.coin_type || item) : value?.coin_type || value
      const tab = getTabByAddress(keyword, Array.from(verifiedTokenMap?.values()), importTokenList)
      console.log('🚀🚀🚀 ~ file: index.tsx:164 ~ useEffect ~ tab:', tab)
      setCurrentTab(tab)
    }
  }, [value, verifiedTokenMap, importTokenList])

  const onDelete = (coinType: string) => {
    const newValues = [...selectTokens]
    if (typeof newValues?.[0] === 'string') {
      const index = newValues.indexOf(coinType)
      newValues.splice(index, 1)
      setSelectTokens(newValues)
    } else {
      const index = newValues.findIndex(ele => ele.coin_type === coinType)
      newValues.splice(index, 1)
      setSelectTokens(newValues)
    }
  }
  return (
    <>
      {showSearchInput && (
        <Box p="0px 16px">
          {showSearchInput && (
            <HStack>
              <SearchInput isWidget={isWidget} inputValue={inputValue} changeInputValue={e => changeInputValue(e)} />
            </HStack>
          )}

          {isShowHotList ? (
            <Suspense
              fallback={
                <Flex marginTop="16px" width={{ base: '100%', lg: '428px' }} flexWrap="wrap" justifyContent="space-between">
                  {[...Array(12)].map((_, index) => (
                    <Skeleton key={index} width="94px" height="16px" margin="0 8px 8px 0" />
                  ))}
                </Flex>
              }
            >
              <CollectListBox
                selectedCoinTypeList={
                  selectType === 'multiple' ? selectTokens?.map(item => (typeof item === 'string' ? item : item.coin_type)) || [] : []
                }
                whiteTokenList={whiteTokenList}
                onSelectToken={(tokenInfo: Token) => selectToken(tokenInfo)}
              />
            </Suspense>
          ) : null}

          {!inputValue && isShowTokenListTab ? (
            <SelectTab<any, any>
              type="borderTab"
              wrapStyle={{
                w: {
                  base: '100%',
                  lg: '395px'
                },
                h: '34px',
                bg: 'none',
                border: 'none',
                marginTop: !isShowHotList ? '12px' : '',
                mb: '4px'
              }}
              itemStyle={{
                // w: '50%',
                marginRight: '40px',
                fontSize: '14px'
              }}
              tabList={tabList}
              currentTab={currentTab}
              handleChangeTab={item => {
                setCurrentTab(item.value)
                setFilterTokenLoading(true)
                setTimeout(() => {
                  setFilterTokenLoading(false)
                }, 300)
              }}
            />
          ) : null}
          {!inputValue && currentTab == 'Default' && isShowLabelTab ? (
            <Box h="12px" />
          ) : // <SelectTab<any, any>
          //   type="outlineTab"
          //   wrapStyle={{
          //     w: {
          //       base: '100%'
          //     },
          //     h: '34px',
          //     bg: isWidget ? 'swap_bg_secondary' : 'bg_secondary',
          //     padding: '4px',
          //     marginTop: '12px'
          //   }}
          //   itemStyle={{
          //     w: `${100 / labelList.length}%`,
          //     // marginRight: '40px',
          //     fontSize: '14px',
          //     borderRadius: '8px'
          //   }}
          //   tabList={labelList}
          //   currentTab={currentLabel}
          //   handleChangeTab={item => {
          //     setCurrentLabel(item.value)
          //     filterTokenWithLabel(item.value, isDcaSelect ? whiteTokenList! : Array.from(verifiedTokenMap?.values()))
          //   }}
          // />
          null}
          {currentTab == 'Imported' && importTokenList && importTokenList.length > 0 && !inputValue ? (
            <Flex p="12px 0 4px" justifyContent="space-between">
              <Text>{importTokenList && importTokenList.length} Custom Tokens</Text>
              <Text
                cursor="pointer"
                _hover={{
                  color: 'text_caption'
                }}
                onClick={() => {
                  delImportTokenList(importTokenList)
                }}
              >
                Clear All
              </Text>
            </Flex>
          ) : null}
        </Box>
      )}

      <Box p="0px">
        <Suspense
          fallback={
            <Flex marginTop="16px" flexDirection="column">
              {[...Array(5)].map((_, index) => (
                <HStack gap="0" key={index} height="64px" padding="0 16px">
                  <SkeletonCircle size="9" />
                  <VStack gap="4px" ml="4px" align="flex-start">
                    <Skeleton height="4" width="100px" />
                    <Skeleton height="4" width="150px" />
                  </VStack>
                </HStack>
              ))}
            </Flex>
          }
        >
          <TokenList
            onGoplusTokenClick={onGoplusTokenClick}
            tokenList={tokenList}
            keyword={inputValue}
            currentLabel={currentLabel}
            currentTab={currentTab}
            value={selectType === 'multiple' ? selectTokens : value}
            isDisableSelectTokenItem={isDisableSelectTokenItem}
            isShowCollectListBox={isShowCollectListBox}
            isShowTokenName={isShowTokenName}
            isShowTokenListTab={isShowTokenListTab}
            tokenListMaxHeight={tokenListMaxHeight}
            noDataHaveImg={noDataHaveImg}
            noClickImportItem={noClickImportItem}
            isShowOperate={isShowOperate}
            isShowCoinInfo={isShowCoinInfo}
            bg={bg}
            onSelectToken={(tokenInfo: Token) => selectToken(tokenInfo)}
            onClose={onClose}
            notAllowedSelect={token =>
              selectTokens?.length >= maxSelectNum &&
              (typeof selectTokens?.[0] === 'string'
                ? !selectTokens?.includes(token?.coin_type)
                : !selectTokens?.some(item => item?.coin_type === token?.coin_type))
            }
          />
          {selectType === 'multiple' && (
            <VStack w="100%" p="16px" gap="16px">
              <HStack w="100%" justify="space-between">
                <Text as="div">
                  Selected Token (
                  <Text as="span" color={selectTokens?.length >= maxSelectNum ? 'primary' : 'text_caption'}>
                    {selectTokens?.length}
                  </Text>
                  /{maxSelectNum})
                </Text>
                <HStack gap="0">
                  {selectTokens?.map(token => (
                    <SingleToken
                      key={token?.coin_type || token}
                      coinType={token?.coin_type || token}
                      onDelete={() => onDelete(token?.coin_type || token)}
                    />
                  ))}
                </HStack>
              </HStack>
              <Button
                w="100%"
                h="52px"
                borderRadius="12px"
                fontSize="18px"
                fontWeight="500"
                onClick={() => {
                  onSelectToken(selectTokens)
                  onClose()
                }}
              >
                Confirm
              </Button>
            </VStack>
          )}
        </Suspense>
      </Box>
    </>
  )
}
export default TokenSelectCard

const SingleToken = ({ coinType, onDelete }: { coinType: string; onDelete: () => void }) => {
  const [showDelete, setShowDelete] = useState(false)
  const { isApp } = useWindowWidth()
  const onMouseEnter = () => {
    setShowDelete(true)
  }
  const onMouseLeave = () => {
    setShowDelete(false)
  }

  return (
    <Box cursor="pointer" pos="relative" onClick={onDelete} onMouseEnter={onMouseEnter} onMouseLeave={onMouseLeave}>
      <SingleTokenInfo coinType={coinType} haveSymbol={false} haveName={false} haveAddress={false} imgBoxStyle={{ w: '28px', h: '28px' }} />
      {(showDelete || isApp) && (
        <Center pos="absolute" border="1px solid" borderColor="block_color" bg="primary" borderRadius="50%" top="-4px" right="-4px">
          <Icon xlinkHref="#icon-icon_close1" fontSize="12px" svgFill="block_color" showHover={false} />
        </Center>
      )}
    </Box>
  )
}
