import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import {
  Box,
  BoxProps,
  Popover,
  PopoverBody,
  PopoverBodyProps,
  PopoverContent,
  PopoverContentProps,
  PopoverProps,
  PopoverTrigger,
  Portal
} from '@chakra-ui/react'
import { useEffect, useRef, useState } from 'react'

interface CetusTooltipProps extends PopoverProps {
  children: React.ReactNode
  tooltip: React.ReactNode
  maxW?: PopoverContentProps['maxW']
  bodyPadding?: string
  showTooltip?: boolean
  needPortal?: boolean
  triggerStyle?: BoxProps
  gutter?: number
  fontSize?: PopoverBodyProps['fontSize']
}

function CetusTooltip({
  children,
  tooltip,
  placement,
  maxW = '320px',
  bodyPadding = '8px',
  showTooltip = true,
  needPortal = true,
  triggerStyle = {},
  gutter = 4,
  fontSize = 'sm'
}: CetusTooltipProps) {
  const { isApp } = useWindowWidth()
  const [isOpen, setIsOpen] = useState(false)
  const triggerRef = useRef<HTMLDivElement>(null)
  const popoverContentRef = useRef<HTMLDivElement>(null)

  // 监听移动端的外部点击
  useEffect(() => {
    if (!isApp || !showTooltip) return

    const handleClickOutside = (e: MouseEvent) => {
      if (triggerRef.current && !triggerRef.current.contains(e.target as Node) && !popoverContentRef.current?.contains(e.target as Node)) {
        setIsOpen(false)
      }
    }

    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [isApp, showTooltip])

  const handleOpen = () => {
    if (showTooltip) {
      setIsOpen(true)
    }
  }

  const trigger = (
    <Box
      as="button"
      ref={triggerRef}
      onClick={e => {
        // 只有在移动端且showTooltip为true时才触发
        if (isApp && showTooltip) {
          e.stopPropagation()
          handleOpen()
        }
      }}
      {...triggerStyle}
    >
      {children}
    </Box>
  )

  const popoverCont = (
    <PopoverContent w="fit-content" maxW={maxW} ref={popoverContentRef}>
      <PopoverBody p={bodyPadding} fontSize={fontSize} w="fit-content">
        {tooltip}
      </PopoverBody>
    </PopoverContent>
  )

  return (
    <Popover
      isLazy
      trigger={isApp ? 'click' : 'hover'}
      isOpen={isApp ? isOpen : undefined} // 只在移动端控制状态
      onClose={() => setIsOpen(false)}
      placement={placement}
      autoFocus={false}
      returnFocusOnClose={false}
      gutter={gutter}
      modifiers={[
        {
          name: 'preventOverflow',
          options: {
            padding: 8 // 页面边缘预留 8px
          }
        }
      ]}
    >
      <PopoverTrigger>{trigger}</PopoverTrigger>
      {showTooltip && (needPortal ? <Portal>{popoverCont}</Portal> : popoverCont)}
    </Popover>
  )
}

export default CetusTooltip
